<main class="mx-auto min-w-0 max-w-7xl space-y-7 overflow-x-hidden p-6">
    <header class="flex min-w-0 flex-wrap items-end justify-between gap-4"><div class="min-w-0"><p class="text-sm font-semibold text-emerald-300">Trusted · resumable preservation intake</p><h1 class="mt-1 text-3xl font-semibold text-white">High-volume photo batches</h1><p class="mt-2 max-w-3xl text-zinc-400">Inventory tens of thousands of local photos, retain them in bounded checkpoints and resume without repeating completed work.</p></div><div class="flex flex-wrap items-center gap-3"><a href="{{ route('intake.index') }}" class="rounded-xl border border-emerald-700 px-4 py-3 text-sm font-semibold text-emerald-200">Open Intake & Review</a><div class="max-w-full rounded-xl border border-emerald-800 bg-emerald-950/30 px-4 py-3 text-sm text-emerald-100">v{{ config('release.version') }} · {{ config('release.name') }}</div></div></header>
    <section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><article class="rounded-xl border border-zinc-700 bg-zinc-900 p-5"><p class="text-sm text-zinc-400">Planned files</p><p class="mt-2 text-3xl font-semibold text-white">{{ number_format($sessions->sum('selected_count')) }}</p></article><article class="rounded-xl border border-zinc-700 bg-zinc-900 p-5"><p class="text-sm text-zinc-400">Retained</p><p class="mt-2 text-3xl font-semibold text-emerald-300">{{ number_format($sessions->sum('imported_count')) }}</p></article><article class="rounded-xl border border-zinc-700 bg-zinc-900 p-5"><p class="text-sm text-zinc-400">Remaining</p><p class="mt-2 text-3xl font-semibold text-amber-300">{{ number_format($sessions->sum('selected_count') - $sessions->sum('processed_count')) }}</p></article><article class="rounded-xl border border-zinc-700 bg-zinc-900 p-5"><p class="text-sm text-zinc-400">Failures isolated</p><p class="mt-2 text-3xl font-semibold text-white">{{ number_format($sessions->sum('failed_count')) }}</p></article></section>
    <section class="min-w-0 rounded-2xl border border-zinc-700 bg-zinc-900 p-6"><div class="flex min-w-0 flex-wrap items-end justify-between gap-4"><div class="min-w-0"><h2 class="text-xl font-semibold text-white">Batch checkpoints</h2><p class="mt-1 text-sm text-zinc-400">Full local paths are never persisted. Every retained file enters the consolidated Intake & Review workspace.</p></div><code class="max-w-full break-all whitespace-normal rounded-lg bg-zinc-950 px-4 py-2 text-xs text-emerald-300">php artisan archive:batch-import ...</code></div><div class="mt-5 min-w-0 space-y-4">@forelse($sessions as $session) @php($progress=$session->selected_count>0?min(100,(int)round(($session->processed_count/$session->selected_count)*100)):0)<article class="min-w-0 rounded-xl border border-zinc-700 bg-zinc-950 p-5"><div class="flex min-w-0 flex-wrap items-start justify-between gap-4"><div class="min-w-0"><p class="text-xs uppercase tracking-wide text-emerald-300">{{ $session->state }}</p><h3 class="mt-1 font-semibold text-white">{{ $session->manifest['source_label'] ?? 'Private photo batch' }}</h3><p class="mt-1 break-all text-xs text-zinc-500">{{ $session->session_id }}</p></div><p class="text-2xl font-semibold text-white">{{ $progress }}%</p></div><div class="mt-4 h-2 overflow-hidden rounded-full bg-zinc-800"><div class="h-full bg-emerald-500" style="width:{{ $progress }}%"></div></div><dl class="mt-4 grid gap-3 text-sm sm:grid-cols-5"><div><dt class="text-zinc-500">Inventory</dt><dd class="font-semibold text-white">{{ number_format($session->selected_count) }}</dd></div><div><dt class="text-zinc-500">Processed</dt><dd class="font-semibold text-white">{{ number_format($session->processed_count) }}</dd></div><div><dt class="text-zinc-500">Retained</dt><dd class="font-semibold text-white">{{ number_format($session->imported_count) }}</dd></div><div><dt class="text-zinc-500">Failed</dt><dd class="font-semibold text-white">{{ number_format($session->failed_count) }}</dd></div><div><dt class="text-zinc-500">Checkpoint</dt><dd class="font-semibold text-white">{{ number_format($session->chunk_size) }}</dd></div></dl></article>@empty<p class="rounded-xl border border-dashed border-zinc-700 p-5 text-zinc-400">No high-volume batch has been inventoried.</p>@endforelse</div></section>
    <section class="grid gap-5 lg:grid-cols-[1.4fr_0.6fr]"><article class="rounded-2xl border border-zinc-700 bg-zinc-900 p-6"><h2 class="text-xl font-semibold text-white">Recent file outcomes</h2><div class="mt-4 grid gap-3 sm:grid-cols-2">@forelse($recentItems as $item)<div class="rounded-lg bg-zinc-950 p-4"><div class="flex justify-between gap-3"><strong class="truncate text-white">{{ $item->original_name }}</strong><span class="text-xs uppercase {{ $item->state==='retained'?'text-emerald-300':($item->state==='failed'?'text-red-300':'text-amber-300') }}">{{ $item->state }}</span></div><p class="mt-2 text-xs text-zinc-500">Position {{ number_format($item->position) }} · attempt {{ $item->attempt_count }}</p></div>@empty<p class="text-zinc-400">No checkpoint outcomes yet.</p>@endforelse</div></article><aside class="rounded-2xl border border-amber-800 bg-amber-950/20 p-6 text-sm text-amber-100"><h2 class="text-lg font-semibold text-white">Preservation boundary</h2><ul class="mt-4 space-y-3"><li>No browser request carries 30,000 files.</li><li>No source path enters the database or evidence.</li><li>Inventory drift stops processing.</li><li>Failures do not erase successful checkpoints.</li><li>Batch choices use verified originals and reversible suggestions.</li></ul></aside></section>
